function validate([stockPrices]) {
  if (!Array.isArray(stockPrices) || stockPrices.length < 1 || stockPrices.length > 100000) return 'stockPrices needs 1 to 10^5 points.';
  if (stockPrices.some(p => !Array.isArray(p) || p.length !== 2 || p.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000))) return 'Each point is [day, price] with both between 1 and 10^9.';
  if (new Set(stockPrices.map(p => p[0])).size !== stockPrices.length) return 'Days must be distinct.';
  return null;
}

