function minimumLines(stockPrices) {
  const n = stockPrices.length;
  if (n < 2) {
    return 0;
  }
  stockPrices.sort((a, b) => a[0] - b[0]);
  let lines = 1;
  for (let i = 2; i < n; i++) {
    const [x0, y0] = stockPrices[i - 2];
    const [x1, y1] = stockPrices[i - 1];
    const [x2, y2] = stockPrices[i];
    const left = BigInt(y1 - y0) * BigInt(x2 - x1);
    const right = BigInt(y2 - y1) * BigInt(x1 - x0);
    if (left !== right) {
      lines++;
    }
  }
  return lines;
}

