function minimumLines(stockPrices) {
  // Describe every segment by its slope in lowest terms and count the places where that slope changes.
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const points = stockPrices.map(p => p.slice());
  for (let i = 1; i < points.length; i++)
    for (let j = i; j > 0 && points[j - 1][0] > points[j][0]; j--) [points[j - 1], points[j]] = [points[j], points[j - 1]];
  const keys = [];
  for (let i = 1; i < points.length; i++) {
    const dx = points[i][0] - points[i - 1][0];
    const dy = points[i][1] - points[i - 1][1];
    const g = gcd(Math.abs(dx), Math.abs(dy));
    keys.push((dy / g) + '/' + (dx / g));
  }
  let count = 0;
  for (let i = 0; i < keys.length; i++) if (i === 0 || keys[i] !== keys[i - 1]) count++;
  return count;
}

