function generate(rand, size) {
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  if (size === 'large') {
    // A piecewise-linear walk with rational slopes a/b, so long runs of points share a line.
    const points = [];
    let day = 1 + Math.floor(rand() * 1000);
    let price = 500000000;
    let rise = 1;
    let run = 1;
    for (let i = 0; i < 2000; i++) {
      points.push([day, price]);
      if (rand() < 0.2) {
        run = 1 + Math.floor(rand() * 1000);
        rise = Math.floor(rand() * 2001) - 1000;
      }
      const steps = 1 + Math.floor(rand() * 50);
      day += run * steps;
      price += rise * steps;
    }
    return [shuffle(points)];
  }
  const n = 1 + Math.floor(rand() * 9);
  const days = shuffle(Array.from({ length: 15 }, (_, i) => i + 1)).slice(0, n).sort((a, b) => a - b);
  const prices = [];
  let slope = Math.floor(rand() * 4) - 1;
  for (let i = 0; i < n; i++) {
    if (i === 0) prices.push(0);
    else {
      if (rand() < 0.35) slope = Math.floor(rand() * 4) - 1;
      prices.push(prices[i - 1] + slope * (days[i] - days[i - 1]));
    }
  }
  const lowest = Math.min(...prices);
  return [shuffle(days.map((d, i) => [d, prices[i] - lowest + 1]))];
}
